import{c as e,Q as d,j as o,m as r}from"./chunks/framework.W-g_WCNV.js";const p=JSON.parse('{"title":"Audit log","description":"What gets logged and how to read the audit log.","frontmatter":{"title":"Audit log","description":"What gets logged and how to read the audit log."},"headers":[],"relativePath":"admin/audit-log.md","filePath":"admin/audit-log.md"}'),a={name:"admin/audit-log.md"};function n(i,t,s,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r('<p>The audit log at <code>/audit</code> is an append-only record of every authentication and admin event.</p><h2 id="reading-the-log" tabindex="-1">Reading the log <a class="header-anchor" href="#reading-the-log" aria-label="Permalink to &quot;Reading the log&quot;">​</a></h2><p>Each row shows:</p><ul><li><strong>Time</strong> - <code>HH:MM:SS</code> in server local time</li><li><strong>Event</strong> - dotted code like <code>login.success</code> or <code>totp.failed</code></li><li><strong>User</strong> - avatar, display name (or email if no name is set), and email address. For authentication events a badge shows the method used: Passkey, TOTP, Email OTP, or Password.</li><li><strong>Detail</strong> - additional context, e.g. failure reason or changed field</li><li><strong>IP</strong> - originating IP address</li></ul><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p><strong>Kind chips</strong> - All / Success / Warn / Fail / Info</p><p><strong>Event type chips:</strong></p><ul><li><code>auth</code> - login, OTP, TOTP, passkey, password events</li><li><code>admin</code> - admin panel actions (including admin logins)</li><li><code>oidc</code> - OIDC token events</li></ul><p><strong>Date range</strong> - Today / 7 days / 30 days / 90 days / All (default: 30 days)</p><p><strong>Search</strong> - filters by event code, email, IP, or detail text. The filter icon on any row sets the search to that event.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p>Set a retention period in <strong>Settings - Audit log</strong>. Events older than the configured number of days are deleted automatically (runs on startup and once per day). Set to <code>0</code> to keep all events forever. Default is 90 days.</p><h2 id="event-reference" tabindex="-1">Event reference <a class="header-anchor" href="#event-reference" aria-label="Permalink to &quot;Event reference&quot;">​</a></h2><h3 id="auth-events" tabindex="-1">Auth events <a class="header-anchor" href="#auth-events" aria-label="Permalink to &quot;Auth events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Kind</th><th>Description</th></tr></thead><tbody><tr><td><code>login.success</code></td><td>ok</td><td>Password verified and 2FA passed</td></tr><tr><td><code>login.failure</code></td><td>err</td><td>Wrong password or unknown email</td></tr><tr><td><code>login.passkey</code></td><td>ok</td><td>User authenticated via passkey</td></tr><tr><td><code>otp.sent</code></td><td>info</td><td>Email OTP dispatched</td></tr><tr><td><code>otp.verified</code></td><td>ok</td><td>Email OTP accepted</td></tr><tr><td><code>otp.failed</code></td><td>err</td><td>Wrong OTP code</td></tr><tr><td><code>totp.enrolled</code></td><td>ok</td><td>Authenticator app enrolled</td></tr><tr><td><code>totp.verified</code></td><td>ok</td><td>Authenticator code accepted</td></tr><tr><td><code>totp.failed</code></td><td>err</td><td>Wrong authenticator code</td></tr><tr><td><code>totp.recovery_used</code></td><td>warn</td><td>Recovery code consumed</td></tr><tr><td><code>totp.revoked</code></td><td>warn</td><td>TOTP enrollment removed</td></tr><tr><td><code>passkey.registered</code></td><td>ok</td><td>New passkey added</td></tr><tr><td><code>passkey.revoked</code></td><td>warn</td><td>Passkey removed</td></tr><tr><td><code>password.changed</code></td><td>ok</td><td>Password updated</td></tr><tr><td><code>password.reset_requested</code></td><td>info</td><td>Reset link sent</td></tr><tr><td><code>password.reset_completed</code></td><td>ok</td><td>Password reset via link</td></tr><tr><td><code>password.reset_invalid</code></td><td>err</td><td>Invalid or expired reset token used</td></tr><tr><td><code>session.revoked</code></td><td>warn</td><td>Session terminated</td></tr></tbody></table><h3 id="admin-events" tabindex="-1">Admin events <a class="header-anchor" href="#admin-events" aria-label="Permalink to &quot;Admin events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Kind</th><th>Description</th></tr></thead><tbody><tr><td><code>admin.login</code></td><td>ok</td><td>Admin signed in with password</td></tr><tr><td><code>admin.login.passkey</code></td><td>ok</td><td>Admin signed in with passkey</td></tr><tr><td><code>admin.login_failed</code></td><td>err</td><td>Admin login attempt failed</td></tr><tr><td><code>admin.logout</code></td><td>info</td><td>Admin signed out</td></tr><tr><td><code>admin.password_set</code></td><td>warn</td><td>Admin set a user&#39;s password directly</td></tr><tr><td><code>user.created</code></td><td>ok</td><td>New user account created</td></tr><tr><td><code>user.disabled</code></td><td>warn</td><td>Account disabled</td></tr><tr><td><code>user.enabled</code></td><td>ok</td><td>Account re-enabled</td></tr><tr><td><code>user.deleted</code></td><td>warn</td><td>User account permanently deleted</td></tr></tbody></table>',17)])])}const u=e(a,[["render",n]]);export{p as __pageData,u as default};
